      {
        "name": "Code Quality",
        "passed": true,
        "reason": "Clean, well-structured TypeScript with strong typing, factory pattern for client creation, proper async/await, descriptive variable names, and good separation of concerns."
      },
      {
        "name": "Correct @azure/ Scoped Packages",
        "passed": true,
        "reason": "All dependencies use @azure/ scoped packages: @azure/event-hubs, @azure/eventhubs-checkpointstore-blob, @azure/storage-blob. No deprecated unscoped packages."
