      {
        "name": "Async/Await Pattern",
        "passed": true,
        "reason": "Consistently uses async/await throughout. Top-level async main() function as entry point. No raw .then()/.catch() chains (the single .then() in Promise.race is idiomatic). No callback patterns."
      },
      {
        "name": "Pagination with for-await-of",
        "passed": true,
        "reason": "Not applicable — Event Hubs send/receive scenario has no list/query operations returning PagedAsyncIterableIterator. No pagination anti-patterns present."
      },
      {
        "name": "LRO Pattern (beginXxx + pollUntilDone)",
        "passed": true,
        "reason": "Not applicable — no long-running operations in this Event Hubs scenario. No manual polling loops present."
      },
      {
        "name": "RestError Exception Handling",
        "passed": false,
        "reason": "No RestError import or statusCode-based error handling. processError handler logs the raw error without type checking. The catch in main() also uses generic Error."
      },
      {
        "name": "No Deprecated Packages",
        "passed": true,
        "reason": "No deprecated or legacy Azure packages present. All dependencies are current @azure/* track packages."
      },
      {
        "name": "Logging via @azure/logger",
        "passed": false,
        "reason": "No @azure/logger import or setLogLevel() usage. Only console.log/console.error for output. No AZURE_LOG_LEVEL support."
      },
      {
        "name": "package.json with Correct Dependencies",
        "passed": true,
        "reason": "Valid package.json with all required @azure/* dependencies. Includes tsconfig.json, @types/node, and TypeScript 6.x as devDependencies."
      },
      {
        "name": "@azure/event-hubs and @azure/eventhubs-checkpointstore-blob packages",
        "passed": true,
        "reason": "Both packages present in package.json dependencies."
      },
      {
        "name": "EventHubProducerClient constructor",
        "passed": true,
        "reason": "EventHubProducerClient is instantiated via factory using connection string."
      },
      {
        "name": "createBatch() and EventDataBatch.tryAdd()",
        "passed": true,
        "reason": "producerClient.createBatch() is called, then batch.tryAdd(event) is used in a loop for 10 events with custom properties."
      },
      {
        "name": "sendBatch() for publishing",
        "passed": true,
        "reason": "producerClient.sendBatch(batch) is called after adding all events."
      },
      {
        "name": "EventHubConsumerClient with BlobCheckpointStore",
        "passed": true,
        "reason": "EventHubConsumerClient is constructed with BlobCheckpointStore created from ContainerClient."
      },
      {
        "name": "subscribe() with SubscriptionEventHandlers",
        "passed": true,
        "reason": "consumerClient.subscribe() is called with processEvents and processError handlers."
      },
      {
        "name": "updateCheckpoint() in processEvents handler",
        "passed": true,
        "reason": "context.updateCheckpoint(lastMatchingEvent) is called within the processEvents handler after processing events."
      },
      {
        "name": "close() for cleanup",
        "passed": true,
        "reason": "subscription.close(), consumerClient.close(), and producerClient.close() are all called in the closeResources function, invoked in finally block and signal handlers."
      }
